EXPORT ZZT_STDBAD() BEGIN
LOCAL R,E,O:={};
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_FAIL(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_FAIL(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,1),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_FAIL(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,-1),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=1; A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_FAIL(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[0,1,1,3]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
HComplex:=0; A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_FAIL(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D, V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;

EXPORT ZZT_STDHOLD() BEGIN
LOCAL R,E,O:={}; HComplex:=1;
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_FAIL(2)),ZZT_TICK(3,4),ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1)],[ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_FAIL(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1)],[ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=ZZT_FAIL(2); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=[[(ZZT_TICK(1,1),ZZT_FAIL(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]]; THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D, V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;

EXPORT ZZT_STDHOLD() BEGIN
LOCAL R,E,O:={}; HComplex:=1;
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(0,ZZT_FAIL(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(-2.0,ZZT_FAIL(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_FAIL(1),-2.0),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_FAIL(1),0),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_FAIL(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),(8,-5)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_FAIL0()),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D, V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;
ZZT_FAIL0() BEGIN A:=A*10+2; RETURN 1/0; END;

EXPORT ZZT_STDHOLD() BEGIN
LOCAL R,E,O:={}; HComplex:=1;
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_BADINDEX(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_BADTYPE(2)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[0,1,1,3]]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D, V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;
ZZT_BADINDEX(D) BEGIN LOCAL L:={1,2}; A:=A*10+D; RETURN L(3); END;
ZZT_BADTYPE(D) BEGIN A:=A*10+D; RETURN ABS({}); END;

EXPORT ZZT_ENCZERO() BEGIN
LOCAL R:=0, gotError:=0; HComplex:=1; A:=0;
IFERR R:=stddev([[(ZZT_TICK(1,1),ZZT_FAIL()),ZZT_TICK(3,4)],[ZZT_TICK(4,3),ZZT_TICK(5,8)]],[[ZZT_TICK(6,0),ZZT_TICK(7,1),ZZT_TICK(8,1),ZZT_TICK(9,3)]]); THEN gotError:=1; END;
RETURN {A,gotError,TYPE(R),STRING(R)};
END;
ZZT_TICK(digit,ret) BEGIN A:=A*10+digit; RETURN ret; END;
ZZT_FAIL() BEGIN A:=A*10+2; RETURN 1/0; END;
